import sys, os, csv, json, gzip, io, re
from datetime import datetime, timezone, timedelta, date
from decimal import Decimal, ROUND_HALF_UP
from zoneinfo import ZoneInfo

UTC = timezone.utc


def read_text(path):
    with open(path, 'rb') as f:
        b = f.read()
    if b[:2] == b'\x1f\x8b':
        b = gzip.decompress(b)
    t = b.decode('utf-8')
    if t.startswith('\ufeff'):
        t = t[1:]
    return t


def lines_of(path):
    return [l for l in read_text(path).splitlines() if l.strip() != '']


def to_epoch(naive, tz, fold=0):
    return int(naive.replace(tzinfo=tz, fold=fold).timestamp())


def local_epoch(naive, tz, fold=0):
    # epoch of local wall time; fold picks the occurrence of repeated times
    dt = naive.replace(tzinfo=tz, fold=fold)
    return int(dt.astimezone(UTC).timestamp())


def std_offset(tz, year):
    a = datetime(year, 1, 1, tzinfo=tz).utcoffset()
    b = datetime(year, 7, 1, tzinfo=tz).utcoffset()
    return min(a, b)


def parse_dir(s):
    s = s.strip().upper()
    return 'IN' if s in ('IN', 'CLOCK_IN', 'K', 'I') else 'OUT'


def parse_abbr(path, tz, out):
    hdr = None
    for line in lines_of(path):
        row = next(csv.reader([line]))
        row = [c.strip() for c in row]
        if 'Badge' in row and 'Punch' in row:
            hdr = row
            continue
        if hdr is None:
            continue
        d = dict(zip(hdr, row))
        m, dd, y = map(int, d['Date'].split('/'))
        t = d['Time'].strip()
        ap = None
        mm = re.match(r'^(\d+):(\d+):(\d+)\s*([AaPp][Mm])?$', t)
        h, mi, s = int(mm.group(1)), int(mm.group(2)), int(mm.group(3))
        if mm.group(4):
            ap = mm.group(4).upper()
            h = h % 12 + (12 if ap == 'PM' else 0)
        z = d.get('Zone', '').upper()
        fold = 0 if z.endswith('DT') else 1
        naive = datetime(y, m, dd, h, mi, s)
        out.append((d['Record'], d['Badge'], parse_dir(d['Punch']), local_epoch(naive, tz, fold)))


def parse_epoch(path, tz, out):
    schema = 1
    for line in lines_of(path):
        o = json.loads(line)
        if 'schema' in o and 'heartbeat' not in o and len(o) == 1:
            schema = int(o['schema'])
            continue
        if o.get('heartbeat'):
            continue
        if schema == 2:
            pid, emp, dr, ts = o['punch_id'], o['employee'], o['direction'], int(o['epoch_ms']) // 1000
        else:
            pid, emp, dr = o['id'], o['emp'], o['dir']
            ts = int(o['ts_ms']) // 1000 if 'ts_ms' in o else int(o['ts'])
        out.append((str(pid), emp, parse_dir(dr), ts))


def parse_offset(path, tz, out):
    txt = lines_of(path)
    rdr = csv.DictReader(txt, delimiter=';')
    for d in rdr:
        dt = datetime.fromisoformat(d['timestamp'])
        out.append((d['punch_id'], d['employee'], parse_dir(d['event']), int(dt.timestamp())))


def parse_legacy(path, tz, out):
    off = None
    for line in lines_of(path):
        t = line[0]
        if t == 'H':
            m = re.match(r'^([+-])(\d{2})(\d{2})$', line[13:18].strip())
            if m:
                sec = (int(m.group(2)) * 60 + int(m.group(3))) * 60
                off = timedelta(seconds=sec if m.group(1) == '+' else -sec)
            else:
                off = None
        elif t == 'D':
            pid = line[1:9]
            badge = line[9:15].strip()
            dr = line[15]
            ts = line[16:30]
            naive = datetime.strptime(ts, '%Y%m%d%H%M%S')
            o = off if off is not None else std_offset(tz, naive.year)
            epoch = int((naive - o).replace(tzinfo=UTC).timestamp())
            out.append((pid, 'E' + badge, parse_dir(dr), epoch))


def parse_de(path, tz, out):
    txt = lines_of(path)
    for d in csv.DictReader(txt, delimiter='\t'):
        d = {k.strip(): (v or '').strip() for k, v in d.items()}
        dd, m, y = map(int, d['Datum'].split('.'))
        h, mi = map(int, d['Uhrzeit'].split(':')[:2])
        fold = 0 if d['Zeitzone'].upper() == 'MESZ' else 1
        out.append((d['Nr'], d['Ausweis'], parse_dir(d['Buchung']), local_epoch(datetime(y, m, dd, h, mi), tz, fold)))


def parse_localcsv(path, tz, out):
    for d in csv.DictReader(lines_of(path)):
        naive = datetime.strptime(d['local_time'].strip(), '%Y-%m-%d %H:%M:%S')
        out.append((d['punch_ref'], d['employee_id'], parse_dir(d['direction']), local_epoch(naive, tz, 0)))


def parse_localjsonl(path, tz, out):
    for line in lines_of(path):
        o = json.loads(line)
        p = o.get('punch')
        if not p:
            continue
        naive = datetime.strptime(p['at'].strip(), '%Y-%m-%d %H:%M:%S')
        out.append((str(int(p['id'])) if not isinstance(p['id'], str) else p['id'], p['badge'],
                    parse_dir(p['type']), local_epoch(naive, tz, 0)))


PARSERS = {'abbr-csv': parse_abbr, 'epoch-jsonl': parse_epoch, 'offset-csv': parse_offset,
           'legacy-fixed': parse_legacy, 'de-tsv': parse_de, 'local-csv': parse_localcsv,
           'local-jsonl': parse_localjsonl}


def money(d):
    return str(d.quantize(Decimal('0.01'), rounding=ROUND_HALF_UP))


def main(inp, outfile):
    period = json.load(open(os.path.join(inp, 'period.json')))
    pstart = date.fromisoformat(period['start'])
    pend = date.fromisoformat(period['end'])
    cutoff = datetime.fromisoformat(period['corrections_cutoff'].replace('Z', '+00:00'))
    sites = {}
    with open(os.path.join(inp, 'sites.csv'), newline='', encoding='utf-8-sig') as f:
        for r in csv.DictReader(f):
            sites[r['site'].strip()] = (ZoneInfo(r['timezone'].strip()), r['format'].strip())
    emps = {}
    with open(os.path.join(inp, 'employees.csv'), newline='', encoding='utf-8-sig') as f:
        for r in csv.DictReader(f):
            emps[r['employee_id'].strip()] = r['home_site'].strip()
    rates = {}
    with open(os.path.join(inp, 'rates.csv'), newline='', encoding='utf-8-sig') as f:
        for r in csv.DictReader(f):
            rates.setdefault(r['employee_id'].strip(), []).append(
                (date.fromisoformat(r['effective_from'].strip()), Decimal(r['hourly_rate'].strip())))
    for v in rates.values():
        v.sort()

    # 1 collect
    punches = {}  # (site,id) -> [emp, dir, ts]
    ever = set()
    for site, (tz, fmt) in sites.items():
        d = os.path.join(inp, 'exports', site)
        if not os.path.isdir(d):
            continue
        for root, _, files in os.walk(d):
            for fn in sorted(files):
                out = []
                PARSERS[fmt](os.path.join(root, fn), tz, out)
                for pid, emp, dr, ts in out:
                    k = (site, pid)
                    ever.add(k)
                    if k not in punches:
                        punches[k] = [emp, dr, ts]

    # 2 corrections
    corr = []
    cdir = os.path.join(inp, 'corrections')
    if os.path.isdir(cdir):
        for root, _, files in os.walk(cdir):
            for fn in files:
                txt = lines_of(os.path.join(root, fn))
                for r in csv.DictReader(txt):
                    r = {k: (v or '').strip() for k, v in r.items() if k}
                    if r.get('correction_id') == 'correction_id':
                        continue
                    corr.append(r)
    def ckey(r):
        return (datetime.fromisoformat(r['issued_at'].replace('Z', '+00:00')), r['correction_id'])
    corr.sort(key=ckey)
    applied = 0
    for r in corr:
        if ckey(r)[0] > cutoff:
            continue
        k = (r['site'], r['punch_id'])
        a = r['action'].lower()
        if a == 'void':
            if k in punches:
                del punches[k]; applied += 1
        elif a == 'set':
            if k in punches:
                punches[k][2] = int(datetime.fromisoformat(r['time']).timestamp()); applied += 1
        elif a == 'add':
            if k not in ever and k not in punches:
                punches[k] = [r['employee'], parse_dir(r['type']), int(datetime.fromisoformat(r['time']).timestamp())]
                ever.add(k); applied += 1

    byemp = {}
    for (site, pid), (emp, dr, ts) in punches.items():
        if emp in emps and site in sites:
            byemp.setdefault(emp, []).append((ts, 0 if dr == 'OUT' else 1, site, pid, dr))

    def rnd(ts, tz):
        off = int(datetime.fromtimestamp(ts, UTC).astimezone(tz).utcoffset().total_seconds())
        return (ts + off + 180) // 360 * 360 - off

    exc = {'open_shifts': 0, 'orphan_outs': 0, 'duplicates_dropped': 0, 'corrections_applied': applied}
    res = {e: dict(shifts=0, paid_minutes=0, overtime_minutes=0, night_minutes=0, gross=Decimal(0)) for e in emps}

    for emp, lst in byemp.items():
        hz = sites[emps[emp]][0]
        def workday(ts):
            return datetime.fromtimestamp(ts, UTC).astimezone(hz).date()
        lst.sort()
        kept = []
        last = None
        for ts, _, site, pid, dr in lst:
            tz = sites[site][0]
            r = rnd(ts, tz)
            if last is not None and last[1] == dr and ts - last[0] <= 300:
                if pstart <= workday(r) <= pend:
                    exc['duplicates_dropped'] += 1
                continue
            last = (ts, dr)
            kept.append((r, dr, site))
        shifts = []
        i = 0
        n = len(kept)
        def inper(r):
            return pstart <= workday(r) <= pend
        while i < n:
            r, dr, site = kept[i]
            if dr == 'IN':
                if i + 1 < n and kept[i + 1][1] == 'OUT' and kept[i + 1][0] - r <= 16 * 3600:
                    shifts.append((r, kept[i + 1][0], site))
                    i += 2
                    continue
                if inper(r):
                    exc['open_shifts'] += 1
            else:
                if inper(r):
                    exc['orphan_outs'] += 1
            i += 1
        # shifts in period
        rows = []
        for a, b, site in shifts:
            wd = workday(a)
            if not (pstart <= wd <= pend):
                continue
            tz = sites[site][0]
            worked = max(0, (b - a) // 60)
            paid = worked - 30 if worked > 360 else worked
            night = 0
            t = a
            while t < b:
                lt = datetime.fromtimestamp(t, UTC).astimezone(tz)
                if lt.hour >= 22 or lt.hour < 6:
                    night += min(6, (b - t) // 60)
                t += 360
            night = min(night, paid)
            rows.append([a, wd, paid, night, 0])
        rows.sort(key=lambda x: x[0])
        daily = {}
        for row in rows:
            used = daily.get(row[1], 0)
            reg = max(0, min(row[2], 480 - used))
            dot = row[2] - reg
            daily[row[1]] = used + row[2]
            row[4] = dot
            row.append(row[2] - dot)  # non-daily-OT minutes
        weekly = {}
        for row in rows:
            wk = row[1] - timedelta(days=row[1].weekday())
            used = weekly.get(wk, 0)
            nd = row[5]
            wot = max(0, used + nd - 2400) - max(0, used - 2400)
            weekly[wk] = used + nd
            row[4] += wot
        R = res[emp]
        for a, wd, paid, night, ot in rows:
            rate = None
            for eff, v in rates.get(emp, []):
                if eff <= wd:
                    rate = v
            if rate is None:
                rate = Decimal(0)
            reg = paid - ot
            pay = rate * (Decimal(reg) + Decimal('1.5') * ot) / 60 + rate * Decimal('0.15') * night / 60
            R['shifts'] += 1
            R['paid_minutes'] += paid
            R['overtime_minutes'] += ot
            R['night_minutes'] += night
            R['gross'] += pay

    out = {'period': {'start': period['start'], 'end': period['end']}, 'employees': {}, 'exceptions': exc}
    tot = dict(shifts=0, paid_minutes=0, overtime_minutes=0, night_minutes=0)
    tg = Decimal(0)
    for e in sorted(emps):
        R = res[e]
        g = R['gross'].quantize(Decimal('0.01'), rounding=ROUND_HALF_UP)
        out['employees'][e] = {k: R[k] for k in tot}
        out['employees'][e]['gross'] = money(g)
        for k in tot:
            tot[k] += R[k]
        tg += g
    tot['gross'] = money(tg)
    out['totals'] = tot
    os.makedirs(os.path.dirname(os.path.abspath(outfile)), exist_ok=True)
    with open(outfile, 'w') as f:
        json.dump(out, f, indent=1)


if __name__ == '__main__':
    main(sys.argv[1], sys.argv[2])
